using System;using System.IO;using System.Drawing.Imaging;using MyDay.Windows.Core;
class ExportStudioArt {static void Main(string[] args){string root=Path.GetFullPath(args[0]);string folder=Path.GetFullPath(Path.Combine(root,"app/src/main/assets/studio"));if(!folder.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Outside workspace");Directory.CreateDirectory(folder);foreach(string kind in RoomArt.Kinds)using(var image=RoomArt.Image(kind))image.Save(Path.Combine(folder,kind+".png"),ImageFormat.Png);Console.WriteLine("Six first-party room assets exported.");}}
